INSERT INTO "public"."flashcards" ("id", "deck_id", "term", "full_term", "definition", "category", "lesson_reference", "display_order", "created_at") VALUES ('a1b2c3d4-0001-0001-0001-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Photo Resolution (Min/Preferred)', null, 'Minimum: 1024x768 pixels. Preferred: 1600x1200 pixels for clarity in documentation.', 'Photography', '4', '1', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Required Aspect Ratio', null, '4:3 aspect ratio is required for all inspection photos.', 'Photography', '4', '2', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Photo Orientation Rule', null, 'ALL photos must be HORIZONTAL (landscape). Vertical photos are the #1 rejection reason.', 'Photography', '4', '3', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Never Include in Photos', null, 'People and time/date stamps burned into the image. Both cause immediate rejection.', 'Photography', '4', '4', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Basic 6 Photos', null, 'Street Sign, House Number, Front Elevation, Front Left Angle, Front Right Angle, Street Views (L&R).', 'Photography', '4', '5', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Context Shot vs Detail Shot', null, 'Context shows WHERE (full wall/area). Detail shows WHAT (specific damage with scale reference).', 'Photography', '4', '6', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000007', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Keep Vertical Lines Vertical', null, 'Critical framing rule: building edges should be straight, not leaning. Avoid tilting camera.', 'Photography', '4', '7', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000008', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Photo Self-Check Question', null, 'Can someone else identify the location and condition without reading your notes?', 'Photography', '4', '8', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000009', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Bad Address Photo', null, 'House number is cropped, blurry, or unreadable. Always verify number is clear before leaving.', 'Photography', '4', '9', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000010', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Good Damage Photo Set', null, 'Wide shot showing location + close-up with scale reference (ruler or measuring tape).', 'Photography', '4', '10', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000011', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Bathroom Photo Mistake', null, 'Capturing your reflection in the mirror. Position yourself to avoid mirror selfies.', 'Photography', '4', '11', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000012', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Front Elevation Rule', null, 'Straight-on shot with 5% open space on all sides to show full context including roofline.', 'Photography', '4', '12', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0001-000000000013', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Exit the Vehicle Rule', null, 'NEVER take photos through windshield. Car parts in frame = immediate rejection.', 'Photography', '4', '13', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'When to Start Photos', null, 'AFTER knocking on the door to check if insured is present. Introduce yourself first.', 'Client Interaction', '5', '14', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'If Asked to Leave', null, 'Apologize for inconvenience and leave immediately. Do not take more photos or argue.', 'Client Interaction', '5', '15', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Door Hanger Placement', null, 'NEVER inside mailbox or between door and frame. Hang on door handle or leave at doorstep.', 'Client Interaction', '5', '16', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Building Trust Tip', null, 'Smile genuinely when they open the door. Silent communication matters.', 'Client Interaction', '5', '17', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Owner Present Protocol', null, 'Point out what you are photographing as you go. Answer questions briefly but honestly.', 'Client Interaction', '5', '18', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0002-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Pre-Trip Check', null, 'Confirm access or appointment if one was scheduled. Check for gate codes and special instructions.', 'Client Interaction', '5', '19', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Dangerous Liability Action', null, 'Take a photo of the hazard AND contact your FIM/Customer Service to describe it immediately.', 'Safety & Hazards', '6', '20', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Step Hazard Rule', null, 'Missing rails on both sides for steps 10 inches or higher must be documented.', 'Safety & Hazards', '6', '21', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Baluster Spacing', null, 'Greater than 4 inches is considered a hazard. Document with measurement.', 'Safety & Hazards', '6', '22', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Unsecured Dog Protocol', null, 'Do not approach. Document from public sidewalk if possible. Note "dog on property" in report.', 'Safety & Hazards', '6', '23', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Criminal Activity Response', null, 'Leave immediately, do not take photos, contact client and local authorities.', 'Safety & Hazards', '6', '24', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0003-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Structural Damage Protocol', null, 'Do not enter. Document from outside. Note "unsafe conditions prevented interior inspection."', 'Safety & Hazards', '6', '25', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'PCR', null, 'Property Condition Report - standardized form documenting property status.', 'Industry Terms', '2', '26', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'REO', null, 'Real Estate Owned - property the bank has taken back through foreclosure.', 'Industry Terms', '2', '27', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'QC', null, 'Quality Control - the review process your work goes through before payment.', 'Industry Terms', '2', '28', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'SOP', null, 'Standard Operating Procedure - the rules you must follow for each client.', 'Industry Terms', '2', '29', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'INT/EXT', null, 'Interior/Exterior - which parts of property to document per the work order.', 'Industry Terms', '2', '30', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'SLA', null, 'Service Level Agreement - the deadline for completing and submitting your inspection.', 'Industry Terms', '6', '31', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000007', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'BPO', null, 'Broker Price Opinion - property valuation done by licensed real estate professionals.', 'Industry Terms', '1', '32', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000008', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'FIM', null, 'Field Inspector Manager - your point of contact at the service company.', 'Industry Terms', '6', '33', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000009', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Chargeback', null, 'Unpaid work due to errors, late submission, or rejected photos.', 'Industry Terms', '6', '34', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0004-000000000010', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Net 30/Net 15', null, 'Payment 30 or 15 days after invoice approval. Not instant pay.', 'Industry Terms', '1', '35', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0005-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Vandalism', null, 'Intentional damage - graffiti, broken windows from outside, deliberate destruction.', 'Damage Terms', '2', '36', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0005-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Deferred Maintenance', null, 'Neglect over time - peeling paint, overgrown lawn, clogged gutters.', 'Damage Terms', '2', '37', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0005-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Wear and Tear', null, 'Normal aging - faded carpet, minor scratches, weathered surfaces.', 'Damage Terms', '2', '38', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0005-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Glazing Damage', null, 'Professional term for broken window. Never say "broken window" in reports.', 'Damage Terms', '2', '39', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0005-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Code Violation', null, 'Something that violates local building codes - requires professional assessment.', 'Damage Terms', '3', '40', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Occupied Status', null, 'Evidence of current habitation - people, furniture, utilities on.', 'Occupancy', '2', '41', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Vacant Status', null, 'No occupancy but property is maintained. No people but no neglect.', 'Occupancy', '2', '42', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Abandoned Status', null, 'No occupancy AND property shows neglect - overgrown, mail piled up.', 'Occupancy', '2', '43', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Unknown Status', null, 'Unable to determine - blocked access, safety concern, conflicting indicators.', 'Occupancy', '2', '44', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Occupancy Indicators', null, 'Cars in driveway, trash cans out, well-kept porch, curtains in windows.', 'Occupancy', '2', '45', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0006-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Vacancy Indicators', null, 'Mail piled up, overgrown lawn, no window coverings, notices on door.', 'Occupancy', '2', '46', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Observation Only Rule', null, 'Report what you SEE, not WHY. "Water stain on ceiling" not "roof leak."', 'Scope of Practice', '3', '47', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Magic Qualifier Phrases', null, '"Appears to be," "Observed what appears to be," "Possible indication of."', 'Scope of Practice', '3', '48', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Field vs Home Inspector', null, 'Field documents what they see. Home diagnoses why it is broken. Do not cross the line.', 'Scope of Practice', '3', '49', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'No Diagnosis Rule', null, 'Never speculate on causes. "Foundation crack observed" not "settlement damage."', 'Scope of Practice', '3', '50', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'No Cost Estimates', null, 'Never recommend repairs or estimate costs unless specifically ordered (rare).', 'Scope of Practice', '3', '51', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0007-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'No Value Opinions', null, 'Never discuss property value or marketability unless doing a BPO.', 'Scope of Practice', '3', '52', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Night Before Prep', null, 'Review orders, note gate codes, map route, charge devices, pack field bag.', 'Workflow', '5', '53', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Route Optimization', null, 'Group by zip code, start farthest and work back, interior during business hours.', 'Workflow', '5', '54', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Property Arrival Sequence', null, 'Park on street, photo street sign, photo house number, knock, then 6-angle exterior.', 'Workflow', '5', '55', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Before Leaving Property', null, 'Review all photos for quality, verify required shots, upload to cloud immediately.', 'Workflow', '5', '56', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', '10-Second Grab Rule', null, 'Everything needed for first 5 minutes must be reachable in under 10 seconds.', 'Workflow', '5', '57', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Upload Proof Folder', null, 'Store portal confirmation screenshots to prove successful submission.', 'Workflow', '5', '58', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000007', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Parking Best Practice', null, 'Park on the street, not in driveway. Looks presumptuous and may block occupants.', 'Workflow', '5', '59', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0008-000000000008', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Order Review Timing', null, 'Review orders night before. Inspectors who prep complete 30% more orders.', 'Workflow', '5', '60', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Essential Day 1 Kit', null, 'Phone, power bank, measuring tape, clipboard, pens, door hangers, flashlight.', 'Field Kit', '5', '61', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Week 1 Additions', null, 'Dedicated camera, tablet, small ruler for scale, PPE (vest, gloves, N95).', 'Field Kit', '5', '62', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'PPE Minimum', null, 'Safety vest, gloves, and N95 mask should always be in your field bag.', 'Field Kit', '5', '63', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Scale Reference Tool', null, 'Small ruler to provide scale in damage photos. Shows actual size of cracks/damage.', 'Field Kit', '5', '64', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Power Bank Importance', null, 'Dead phone = no photos, no GPS, no communication. Ends your workday.', 'Field Kit', '5', '65', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0009-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Vehicle Setup', null, 'Passenger seat: clipboard, snacks. Back seat: field bag. Trunk: ladder, seasonal gear.', 'Field Kit', '5', '66', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0010-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Recommended Attire', null, 'Khakis, polo shirt, neutral jacket, closed-toe shoes. Look boring and legitimate.', 'Professional Conduct', '5', '67', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0010-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Clothing to Avoid', null, 'Tactical/military style, all black, large logos, anything that looks like cop or burglar.', 'Professional Conduct', '5', '68', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0010-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Sunglasses Rule', null, 'Remove when speaking to occupants. Eye contact builds trust.', 'Professional Conduct', '5', '69', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0010-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Door Knock Protocol', null, 'Knock 3 times, step back, keep hands visible, wait 30 seconds before knocking again.', 'Professional Conduct', '5', '70', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0010-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Trust Your Instincts', null, 'If something feels wrong, it probably is. Leave and report. Safety over inspection.', 'Professional Conduct', '5', '71', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0011-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Big Three Mistakes', null, 'Wrong address, blurry photos, late submission. 90% of chargebacks come from these.', 'Common Mistakes', '6', '72', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0011-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'Wrong Address Prevention', null, 'Verify street sign, verify house number, take address photo FIRST before anything else.', 'Common Mistakes', '6', '73', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0001-0011-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000010', 'SLA Miss Protocol', null, 'Communicate BEFORE deadline. "I had a flat tire" is forgivable. Silent lateness is not.', 'Common Mistakes', '6', '74', '2026-01-29 23:43:11.85101+00');